const json = parse(pm.response);
const ME = pm.variables.get('email');
const PW = pm.variables.get('password');
const MAX_MS = Number(pm.environment.get('maxResponseTime') || 2000);
const isJson = (j) => pm.expect(j === undefined ? json : j, 'response body is a valid JSON object').to.be.an('object');
function expectCode(c, label) { pm.test((label || 'Expected result') + ': responseCode is ' + c, function () { isJson(); pm.expect(json.responseCode).to.eql(c); }); }
function expectMsg(m, label) { pm.test((label || 'Expected result') + ": message is '" + m + "'", function () { isJson(); pm.expect(json.message).to.eql(m); }); }
function expectMissing(label) { pm.test((label || 'Expected result') + ': message reports a missing parameter', function () { isJson(); pm.expect(json.message).to.match(/missing/i); }); }
function oneOf(codes, label) {
  pm.test(label + ': responseCode is one of [' + codes.join(', ') + '] (documented behavior)', function () {
    isJson();
    console.log('[documented behavior] ' + label + ' -> responseCode ' + json.responseCode + ' | ' + json.message);
    pm.expect(json.responseCode).to.be.oneOf(codes);
  });
}
function noServerError(label) {
  pm.test((label || 'Request') + ': handled gracefully (no 5xx / responseCode 500)', function () {
    pm.expect(pm.response.code).to.be.below(500);
    if (json) { pm.expect(json.responseCode).to.not.eql(500); }
  });
}
function strict400(label, j) {
  pm.test(label + ': rejected with responseCode 400', function () { isJson(j); pm.expect(j.responseCode).to.eql(400); });
}
function soft(label, j, codes) {
  pm.test(label + ': responseCode is one of [' + codes.join(', ') + '] (documented behavior)', function () {
    isJson(j);
    console.log('[documented behavior] ' + label + ' -> responseCode ' + j.responseCode + ' | ' + j.message);
    pm.expect(j.responseCode).to.be.oneOf(codes);
    pm.expect(j.responseCode).to.not.eql(500);
  });
}


function runVariants(V, check, mainMade) {
  const steps = V.map(v => create('qa_' + uniq() + '@example.com', PW, v.extra));
  chain(steps, function (out) {
    out.forEach(function (o, i) { check(V[i].label, o.json); });
    const made = (mainMade || []).slice();
    out.forEach(function (o, i) { if (code(o) === 201) { made.push([steps[i].form.email, steps[i].form.password]); } });
    cleanup(made);
  });
}

