const REQUIRED = ['name', 'email', 'password', 'title', 'birth_date', 'birth_month', 'birth_year', 'firstname', 'lastname', 'company', 'address1', 'address2', 'country', 'zipcode', 'state', 'city', 'mobile_number'];
pm.test('1. Request method is POST', function () { pm.expect(pm.request.method).to.eql('POST'); });
pm.test('2. Request URL is correct', function () {
  const u = pm.variables.replaceIn(pm.request.url.toString());
  pm.expect(u).to.eql(BASE + '/createAccount');
  pm.expect(u).to.include('/api/createAccount');
});
pm.test('3. Request body is "x-www-form-urlencoded"', function () { pm.expect(pm.request.body.mode).to.eql('urlencoded'); });
pm.test('4. All parameters are present in the request (and have a value)', function () {
  const params = pm.request.body.urlencoded.all().filter(p => !p.disabled);
  const keys = params.map(p => p.key);
  REQUIRED.forEach(k => pm.expect(keys, 'parameter ' + k).to.include(k));
  params.forEach(p => {
    const v = pm.variables.replaceIn(String(p.value));
    pm.expect(v, 'value of ' + p.key).to.not.eql('');
    pm.expect(v, 'unresolved variable in ' + p.key).to.not.include('{{');
  });
});
pm.test('5. Pre-request validation completed successfully', function () {
  pm.expect(pm.variables.get('preRequestDone')).to.eql('true');
  pm.expect(ME).to.match(/^[^\s@]+@[^\s@]+\.[^\s@]+$/);
  pm.expect(pm.environment.get('baseUrl')).to.be.a('string').and.not.empty;
});
