pm.test('8. Response time is less than ' + MAX_MS + ' ms', function () { pm.expect(pm.response.responseTime).to.be.below(MAX_MS); });
pm.test('9. Response is returned in JSON format', function () { isJson(); });
pm.test('10. Response contains responseCode and message', function () {
  isJson(); pm.expect(json).to.have.property('responseCode'); pm.expect(json).to.have.property('message');
});
pm.test('11. responseCode is a number and message is a string', function () {
  isJson(); pm.expect(json.responseCode).to.be.a('number'); pm.expect(json.message).to.be.a('string');
});
pm.test('12. Response contains only responseCode and message (no password / personal data exposed)', function () {
  isJson();
  pm.expect(Object.keys(json).sort()).to.eql(['message', 'responseCode']);
  const txt = pm.response.text();
  [PW, ME, pm.variables.get('mobile_number'), pm.variables.get('firstname')].forEach(v => pm.expect(txt).to.not.include(v));
});
cleanup([[ME, PW]]);

