const ENV_FIELDS = ['name', 'title', 'birth_date', 'birth_month', 'birth_year', 'firstname', 'lastname', 'company', 'address1', 'address2', 'country', 'zipcode', 'state', 'city', 'mobile_number'];
function fields(extra) {
  const o = {};
  ENV_FIELDS.forEach(k => { o[k] = pm.variables.get(k); });
  return Object.assign(o, extra || {});
}
function toForm(o) { return Object.keys(o).map(k => encodeURIComponent(k) + '=' + encodeURIComponent(o[k])).join('&'); }
function parse(r) { try { return JSON.parse(r.text()); } catch (e) { return null; } }
function call(method, path, form, cb) {
  const opt = { url: BASE + path, method: method, header: { 'Content-Type': 'application/x-www-form-urlencoded' } };
  if (form) { opt.body = { mode: 'raw', raw: toForm(form) }; }
  pm.sendRequest(opt, function (err, res) { cb(err, res, res ? parse(res) : null); });
}
function chain(steps, done) {
  const out = [];
  (function next(i) {
    if (i >= steps.length) { return done(out); }
    const s = steps[i];
    call(s.method, s.path, s.form, function (err, res, json) { out.push({ err: err, res: res, json: json }); next(i + 1); });
  })(0);
}
const login = (e, p) => ({ method: 'POST', path: '/verifyLogin', form: { email: e, password: p } });
const del = (e, p) => ({ method: 'DELETE', path: '/deleteAccount', form: { email: e, password: p } });
const create = (e, p, extra) => ({ method: 'POST', path: '/createAccount', form: fields(Object.assign({ email: e, password: p }, extra || {})) });
const details = e => ({ method: 'GET', path: '/getUserDetailByEmail?email=' + encodeURIComponent(e) });
const cleanup = (list, cb) => chain(list.map(x => del(x[0], x[1])), cb || function () {});
const setupCheck = out => out.forEach((o, i) => { if (!o.json) { console.warn('SETUP step ' + i + ' failed', o.err); } });
const code = o => (o && o.json ? o.json.responseCode : undefined);

