const login = (e, p) => ({ method: 'POST', path: '/verifyLogin', form: { email: e, password: p } });
const del = (e, p) => ({ method: 'DELETE', path: '/deleteAccount', form: { email: e, password: p } });
const create = (e, p, extra) => ({ method: 'POST', path: '/createAccount', form: fields(Object.assign({ email: e, password: p }, extra || {})) });
